import React, { useContext, useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  FaSignOutAlt,
  FaChevronDown,
  FaIdCard,
  FaCalendarAlt,
  FaPhoneAlt,
  FaBookOpen,
  FaUser,
  FaTimes,
  FaHome,
} from 'react-icons/fa';
import { AuthContext } from '../../App';

const RoleLabels = {
  STUDENT: 'Student',
  STAFF: 'Staff',
  TRANSPORT: 'Transport',
};

function Topbar({ onOpenHomework }) {
  const { stateAuth, dispatchAuth } = useContext(AuthContext);
  const [showProfileDrawer, setShowProfileDrawer] = useState(false);
  const drawerRef = useRef(null);
  const navigate = useNavigate();

  const user = stateAuth?.user || {};
  const displayName = user.stdnm || user.stfnm || user.drvnm || 'User';
  const roleId = user.stdrolid || user.stfrolid || user.drvid || '';
  const academicYear = user.acdmcyr || '';
  const mobileNo = user.mbleno || '';
  const roleLabel = RoleLabels[(user.typ || '').toUpperCase()] || user.typ || '';

  const getInitials = () => {
    if (!displayName || displayName === 'User') return 'US';
    return displayName
      .split(' ')
      .filter(Boolean)
      .map((s) => s[0])
      .slice(0, 2)
      .join('')
      .toUpperCase();
  };

  useEffect(() => {
    const handleOutsideClick = (event) => {
      if (drawerRef.current && !drawerRef.current.contains(event.target)) {
        setShowProfileDrawer(false);
      }
    };
    document.addEventListener('mousedown', handleOutsideClick);
    return () => document.removeEventListener('mousedown', handleOutsideClick);
  }, []);

  const logout = () => {
    setShowProfileDrawer(false);
    dispatchAuth({ type: 'LOGOUT' });
    navigate('/');
  };

  const goToDashboard = () => {
    setShowProfileDrawer(false);
    navigate('/dashboard');
  };

  const goToProfile = () => {
    setShowProfileDrawer(false);
    navigate('/profile');
  };

  const openHomework = () => {
    setShowProfileDrawer(false);
    if (onOpenHomework) {
      onOpenHomework();
    }
  };

  if (!stateAuth?.user) return null;

  return (
    <div className="user-topbar">
      <div className="user-topbar-left">
        <div className="user-profile-container" ref={drawerRef}>
          <div
            className="user-profile-trigger"
            onClick={() => setShowProfileDrawer(!showProfileDrawer)}
          >
            <div className="user-profile-avatar">{getInitials()}</div>
            <FaChevronDown className="user-profile-chevron" />
          </div>

          {showProfileDrawer && (
            <>
              <div
                className="user-profile-drawer-overlay"
                onClick={() => setShowProfileDrawer(false)}
              />
              <aside className="user-profile-drawer">
                <div className="user-profile-drawer-header">
                  <div className="user-profile-drawer-title">
                    <span className="user-profile-drawer-avatar">{getInitials()}</span>
                    <div>
                      <h5>{displayName}</h5>
                      <span>{user.emlid || ''}</span>
                      {roleLabel && (
                        <span className="user-profile-role">{roleLabel}</span>
                      )}
                    </div>
                  </div>
                  <button
                    className="user-drawer-close"
                    aria-label="Close menu"
                    onClick={() => setShowProfileDrawer(false)}
                  >
                    <FaTimes />
                  </button>
                </div>

                <div className="user-profile-drawer-body">
                  <div className="user-profile-drawer-summary">
                    <div className="user-profile-row">
                      <span><FaIdCard /> Role ID</span>
                      <strong>{roleId || '—'}</strong>
                    </div>
                    <div className="user-profile-row">
                      <span><FaCalendarAlt /> Academic Year</span>
                      <strong>{academicYear || '—'}</strong>
                    </div>
                    <div className="user-profile-row">
                      <span><FaPhoneAlt /> Mobile No</span>
                      <strong>{mobileNo || '—'}</strong>
                    </div>
                  </div>


                  <button className="user-logout-btn user-drawer-logout" onClick={logout}>
                    <FaSignOutAlt className="user-logout-icon" />
                    <span>Logout</span>
                  </button>
                </div>
              </aside>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

export default Topbar;
